package cn.bank.devtool;

import cn.bank.devtool.regression.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Real HTTP and source/document boundary regressions added for rebuild.5. */
public final class UpgradeAuditSuite {
    interface Check { void run() throws Exception; }
    static final List<Map<String,Object>> results=new ArrayList<Map<String,Object>>();
    static Path root; static String origin;
    public static void main(String[] args) throws Exception {
        root=Paths.get(args[0]).toAbsolutePath();
        HttpServer server=HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);
        origin="http://127.0.0.1:"+server.getAddress().getPort();
        server.createContext("/",e->{String path=e.getRequestURI().getPath();byte[] b=Util.bytes(path.equals("/missing")?"{\"ok\":true}":"{\"ok\":true,\"id\":7}");e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.start();
        try {
            check("duplicate-document-json-is-rejected",()->invalid(()->Util.parse(Util.bytes("{\"version\":1,\"version\":2}"))));
            check("source-integer-default-keeps-numeric-type",()->{JsonNode d=scan("", "@GetMapping(\"/x\") public Integer page(@RequestParam(defaultValue=\"20\") Integer size){return size;}");require(d.at("/paths/~1x/get/parameters/0/schema/default").isIntegralNumber());});
            check("source-boolean-default-keeps-boolean-type",()->{JsonNode d=scan("", "@GetMapping(\"/x\") public boolean page(@RequestParam(defaultValue=\"true\") boolean enabled){return enabled;}");require(d.at("/paths/~1x/get/parameters/0/schema/default").isBoolean());});
            check("invalid-numeric-default-is-not-advertised-as-valid",()->{JsonNode d=scan("", "@GetMapping(\"/x\") public int page(@RequestParam(defaultValue=\"oops\") int size){return size;}");require(!d.path("x-coverage").path("complete").asBoolean()&&!d.at("/paths/~1x/get/parameters/0/schema").has("default"));});
            check("source-conflict-status-is-not-rewritten-to-200",()->{JsonNode d=scan("", "@GetMapping(\"/x\") @ResponseStatus(HttpStatus.CONFLICT) public String page(){return \"x\";}");require(d.at("/paths/~1x/get/responses").has("409")&&!d.at("/paths/~1x/get/responses").has("200"));});
            check("source-class-status-is-inherited",()->{JsonNode d=scan("@ResponseStatus(HttpStatus.ACCEPTED)", "@GetMapping(\"/x\") public String page(){return \"x\";}");require(d.at("/paths/~1x/get/responses").has("202"));});
            check("source-method-status-overrides-class",()->{JsonNode d=scan("@ResponseStatus(HttpStatus.ACCEPTED)", "@GetMapping(\"/x\") @ResponseStatus(code=HttpStatus.CREATED) public String page(){return \"x\";}");require(d.at("/paths/~1x/get/responses").has("201"));});
            check("source-inherited-controller-members-require-review",()->{JsonNode d=scan("", "@GetMapping(\"/x\") public String page(){return \"x\";}", " extends BaseController");require(!d.path("x-coverage").path("complete").asBoolean());});
            check("documentation-html-is-an-interface-reference",()->{String h=new String(Reports.html("doc",doc()),StandardCharsets.UTF_8);require(h.contains("data-contract-document")&&h.contains("参数")&&h.contains("200")&&h.contains("/probe"));});
            check("generated-project-has-readable-documents",()->{Map<String,byte[]> f=generated();require(f.containsKey("interface-reference.md")&&f.containsKey("interface-reference.html"));});
            check("generated-controller-declares-json-produce",()->{Map<String,byte[]> f=generated();String s=new String(f.get("src/main/java/com/bank/contract/controller/ContractController.java"),StandardCharsets.UTF_8);require(s.contains("produces = \"application/json\""));});
            check("generated-contract-declares-bodyless-406",()->{JsonNode d=Util.parse(generated().get("openapi.json"));JsonNode r=d.at("/paths/~1contracts/post/responses/406");require(r.isObject()&&!r.has("content"));});
            check("response-header-removal-needs-review",()->{ObjectNode a=doc(),b=a.deepCopy();((ObjectNode)b.at("/paths/~1probe/get/responses/200")).remove("headers");JsonNode r=new CompareService().compare(a,b,Util.JSON.createArrayNode());require(r.path("warnCount").asInt()>0&&!r.path("verdict").asText().equals("PASS"));});
            check("missing-declared-resource-handle-fails-run",()->{ObjectNode s=scenario("missing","/missing");((ObjectNode)s.withArray("steps").get(0)).with("resource").put("pointer","/id").put("type","integer");JsonNode r=run(s);require(r.path("verdict").asText().equals("FAIL")&&r.path("steps").get(0).has("resourceError"));});
            check("wrong-declared-resource-handle-type-fails-run",()->{ObjectNode s=scenario("wrong","/ok");((ObjectNode)s.withArray("steps").get(0)).with("resource").put("pointer","/id").put("type","string");require(run(s).path("verdict").asText().equals("FAIL"));});
            check("valid-resource-handle-stays-tracked",()->{ObjectNode s=scenario("handle","/ok");((ObjectNode)s.withArray("steps").get(0)).with("resource").put("pointer","/id").put("type","integer");JsonNode r=run(s);require(r.path("verdict").asText().equals("PASS")&&r.path("resources").size()==1);});
            check("dynamic-existence-expected-does-not-coerce-string",()->require(!ScenarioRules.assertValue(TextNode.valueOf("value"),"exists",TextNode.valueOf("not-a-boolean"))));
            check("unicode-size-counts-code-points",()->require(ScenarioRules.assertValue(TextNode.valueOf("A\uD83D\uDE00中"),"size",IntNode.valueOf(3))));
            check("non-string-header-values-rejected-before-run",()->{ObjectNode s=scenario("header","/ok");((ObjectNode)s.withArray("steps").get(0)).with("request").with("headers").putObject("X-Mode").put("nested",1);invalid(()->ScenarioRules.check(s));});
            check("extract-required-must-be-a-boolean",()->{ObjectNode s=scenario("extract","/ok");((ObjectNode)s.withArray("steps").get(0)).withArray("extract").addObject().put("name","id").put("source","body").put("pointer","/id").put("type","integer").put("required","false");invalid(()->ScenarioRules.check(s));});
            check("resource-pointer-escape-checked-before-run",()->{ObjectNode s=scenario("pointer","/ok");((ObjectNode)s.withArray("steps").get(0)).with("resource").put("pointer","/bad~2").put("type","integer");invalid(()->ScenarioRules.check(s));});
            check("interrupted-cleanup-is-marked-as-interrupted",()->{Path p=root.resolve("build/upgrade-audit/"+UUID.randomUUID());try(RegressionStore store=new RegressionStore(p)){ObjectNode r=Util.obj().put("id","interrupted").put("state","RUNNING").put("verdict","PASS").put("cleanupStatus","NOT_REQUIRED");r.putArray("steps");r.putArray("cleanupSteps").addObject().put("state","DISPATCHING").put("verdict","INCOMPLETE").put("effectState","UNKNOWN_EFFECT");store.save("runs","interrupted",r);}try(RegressionStore store=new RegressionStore(p)){JsonNode r=store.get("runs","interrupted");require(r.path("cleanupSteps").get(0).path("state").asText().equals("INTERRUPTED")&&r.path("overallVerdict").asText().equals("INCOMPLETE"));}});
            check("declared-bodyless-response-accepts-empty-sample",()->{ObjectNode d=doc();((ObjectNode)d.at("/paths/~1probe/get/responses/200")).remove("content");require(new SampleValidator().validate(d,"GET","/probe","200","application/json","").path("verdict").asText().equals("PASS"));});
            check("declared-bodyless-response-rejects-a-body",()->{ObjectNode d=doc();((ObjectNode)d.at("/paths/~1probe/get/responses/200")).remove("content");require(new SampleValidator().validate(d,"GET","/probe","200","application/json","{}").path("verdict").asText().equals("FAIL"));});
            check("204-whitespace-is-not-an-empty-body",()->{ObjectNode d=doc();((ObjectNode)d.at("/paths/~1probe/get")).with("responses").putObject("204").put("description","empty");require(new SampleValidator().validate(d,"GET","/probe","204","application/json"," ").path("verdict").asText().equals("FAIL"));});
            check("invalid-response-content-does-not-pass-as-empty",()->{ObjectNode d=doc();((ObjectNode)d.at("/paths/~1probe/get/responses/200")).put("content","invalid");require(new SampleValidator().validate(d,"GET","/probe","200","application/json","").path("verdict").asText().equals("INCOMPLETE"));});
            check("invalid-response-object-does-not-pass-as-empty",()->{ObjectNode d=doc();((ObjectNode)d.at("/paths/~1probe/get/responses")).put("200","invalid");require(new SampleValidator().validate(d,"GET","/probe","200","application/json","").path("verdict").asText().equals("INCOMPLETE"));});
            check("preflight-error-names-the-actual-target-java",()->{String script=new String(generated().get("deployment/preflight.sh"),StandardCharsets.UTF_8);require(script.contains("This release requires Java "+PlatformProfile.JAVA+"."));});
            check("junit-step-identities-do-not-collapse-equal-names",()->{ObjectNode r=Util.obj().put("name","duplicate").put("state","FINISHED").put("verdict","PASS").put("cleanupStatus","NOT_REQUIRED");ArrayNode steps=r.putArray("steps");steps.addObject().put("id","a").put("name","same").put("state","FINISHED").put("verdict","PASS");steps.addObject().put("id","b").put("name","same").put("state","FINISHED").put("verdict","PASS");String x=new String(RegressionReports.junit(r),StandardCharsets.UTF_8);require(x.contains("a · same")&&x.contains("b · same"));});
        } finally {server.stop(0);}
        long failed=results.stream().filter(x->!Boolean.TRUE.equals(x.get("passed"))).count();
        Files.write(root.resolve(args[1]),Util.bytes(Util.pretty(Util.mapOf("tests",results.size(),"passed",results.size()-failed,"failed",failed,"results",results))));
        System.out.println("Upgrade audit: "+(results.size()-failed)+"/"+results.size());if(failed>0)System.exit(1);
    }
    static JsonNode scan(String annotation,String methods)throws Exception{return scan(annotation,methods,"");}
    static JsonNode scan(String annotation,String methods,String inheritance)throws Exception{String source="package sample; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; @RestController "+annotation+" public class ProbeController"+inheritance+" {"+methods+"}";Map<String,byte[]> files=new LinkedHashMap<String,byte[]>();files.put("src/main/java/sample/ProbeController.java",Util.bytes(source));return new SourceContractService().scan(ZipFiles.write(files));}
    static ObjectNode doc(){ObjectNode d=Util.obj().put("openapi","3.0.3");d.putObject("info").put("title","audit <script>unsafe</script>").put("version","1");ObjectNode op=d.putObject("paths").putObject("/probe").putObject("get");op.put("summary","probe");ObjectNode response=op.putObject("responses").putObject("200").put("description","ok");response.putObject("headers").putObject("X-Cursor").put("description","next").putObject("schema").put("type","string");response.putObject("content").putObject("application/json").putObject("schema").put("type","object").putObject("properties").putObject("id").put("type","integer");return d;}
    static ObjectNode scenario(String id,String path){ObjectNode s=Util.obj().put("schemaVersion",1).put("id",id).put("name",id);ObjectNode step=s.putArray("steps").addObject().put("id","main").put("name","probe");step.putObject("request").put("method","GET").put("path",path);step.putArray("assertions").addObject().put("source","status").put("op","eq").put("expected",200);return s;}
    static JsonNode run(ObjectNode s)throws Exception{try(RegressionEngine e=new RegressionEngine(root.resolve("build/upgrade-audit/"+UUID.randomUUID()),origin)){e.environment(Util.obj().put("id","env").put("name","audit").put("baseUrl",origin).put("pathPrefix","/").put("authMode","NONE"));e.scenario(s);String id=e.start(s.path("id").asText(),"env","request",Util.mapOf(),null).path("id").asText();long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(10);while(System.nanoTime()<end){JsonNode r=e.get("runs",id);if(r.path("state").asText().equals("FINISHED"))return r;Thread.sleep(10);}throw new AssertionError("timeout");}}
    static Map<String,byte[]> generated()throws Exception{return new GeneratorService().generate(SpecParser.read(Files.readAllBytes(root.resolve("src/main/resources/static/examples/contract-v2-spec.json"))));}
    static void invalid(Check c)throws Exception{try{c.run();}catch(IllegalArgumentException expected){return;}throw new AssertionError("invalid input was accepted");}
    static void require(boolean ok){if(!ok)throw new AssertionError("expected behavior not met");}
    static void check(String name,Check check){Map<String,Object> r=new LinkedHashMap<String,Object>();r.put("name",name);try{check.run();r.put("passed",true);}catch(Throwable e){r.put("passed",false);r.put("error",e.toString());System.out.println("FAIL "+name+": "+e);}results.add(r);}
}
